const c = $('Normaliser').first().json;
if (!/^[^@\s]+@[^@\s]+\.[a-z]{2,}$/i.test(c.email)) return [];
const blacklist=$('Site – Blacklist fraîche').all().map(i=>String(i.json.email||'').trim().toLowerCase()).filter(Boolean);
if(blacklist.includes(c.email))return [];
const text = `Bonjour ${c.nom},

Merci pour votre demande de devis. Nous l'avons bien reçue et nous revenons vers vous sous 24 h.

En attendant, vous pouvez découvrir quelques-uns de nos chantiers : https://www.maison-mb.fr/realisations/

Bien cordialement,
Abdelrahman
Gérant – M&B Rénovation
07 53 30 65 59 · www.maison-mb.fr`;
return [{ json: { to: c.email, subject: 'Votre demande de devis – M&B Rénovation', text } }];
